# 1. Individual pair validation
all_pairs_valid = True
for idx, pair in enumerate(pairs):
    is_valid, reason = validate_pair(pair)
    cleaned, status = clean_sample(pair["raw_asr"], pair["refined_text"])
    words = len(pair["refined_text"].split())
    if not is_valid:
        print(f"FAIL: Sample {idx+1} failed validate_pair: {reason}")
        all_pairs_valid = False
    if status != "kept":
        print(f"FAIL: Sample {idx+1} failed clean_sample: {status}")
        all_pairs_valid = False
    tier = "Short" if words < 25 else ("Medium" if words < 90 else "Long")
    print(f"Sample {idx+1:02d}: Tier={tier:<6} Words={words:<3} validate_pair={is_valid} cleaner={status}")

# 2. Batch validation
is_batch_valid, batch_reason, tier_counts = validate_batch(pairs, min_short=4, min_medium=6, min_long=10)
print(f"\nBatch validation: is_valid={is_batch_valid}, reason='{batch_reason}', tier_counts={tier_counts}")

if all_pairs_valid and is_batch_valid:
    out_path = "scratch/subagent_batch_116.json"
    with open(out_path, "w", encoding="utf-8") as f:
        json.dump(pairs, f, indent=2, ensure_ascii=False)
    print(f"\nSUCCESS: Saved verified batch to {out_path}")
else:
    print("\nFAILED: Issues detected, fixing required.")
    sys.exit(1)
